// Sketch::mergePoints - welding sketch points on drag-release (touch
// snap-join, TZ-19). A dragged endpoint dropped onto another sketch point
// merges into it: every element referencing the dragged point is rewired to
// the target, the dragged point is deleted, and geometry degenerated by the
// weld is pruned. The headline case: the end of an open spline welded onto
// the spline's OWN START leaves a properly closed spline (front() == back()).

#include "modeling/Sketch.h"

#include <gtest/gtest.h>

#include <unordered_set>
#include <vector>

using namespace materializr;

namespace {

std::unordered_set<int> uniqueIds(const SketchSpline& sp) {
    return std::unordered_set<int>(sp.controlPointIds.begin(),
                                   sp.controlPointIds.end());
}

const SketchLine* findLine(const Sketch& sk, int lineId) {
    for (const auto& l : sk.getLines())
        if (l.id == lineId) return &l;
    return nullptr;
}

} // namespace

// TZ-19 expected outcome: welding the END of an open spline onto its own
// START closes the spline with five DISTINCT control points and five sketch
// points - so the setup spline carries SIX control points (the weld deletes
// the dragged end; the closing repeat of the start is not a distinct point).
TEST(SketchMerge, OpenSplineEndOntoStartClosesIt) {
    Sketch sk;
    std::vector<int> ids;
    for (int i = 0; i < 6; ++i)
        ids.push_back(sk.addPoint(glm::vec2(static_cast<float>(i), 0.0f)));
    const int splineId = sk.addSpline(ids);
    ASSERT_EQ(sk.pointCount(), 6);

    EXPECT_TRUE(sk.mergePoints(ids.back(), ids.front()));

    ASSERT_EQ(sk.getSplines().size(), 1);
    const SketchSpline& sp = sk.getSplines().front();
    EXPECT_EQ(sp.id, splineId);
    ASSERT_FALSE(sp.controlPointIds.empty());
    EXPECT_EQ(sp.controlPointIds.front(), sp.controlPointIds.back());
    EXPECT_EQ(uniqueIds(sp).size(), 5);
    EXPECT_EQ(sk.pointCount(), 5);
    EXPECT_TRUE(sk.getPoint(ids.front()));
    EXPECT_FALSE(sk.getPoint(ids.back()));
}

// Two separate lines A-B and C-D: welding C onto B rewires the second line's
// start to B and deletes point C.
TEST(SketchMerge, LineEndpointRewiresToSurvivingPoint) {
    Sketch sk;
    const int a  = sk.addPoint(glm::vec2(0.0f, 0.0f));
    const int b  = sk.addPoint(glm::vec2(10.0f, 0.0f));
    const int c  = sk.addPoint(glm::vec2(20.0f, 0.0f));
    const int d  = sk.addPoint(glm::vec2(30.0f, 0.0f));
    sk.addLine(a, b);
    const int line2 = sk.addLine(c, d);

    EXPECT_TRUE(sk.mergePoints(c, b));

    EXPECT_EQ(sk.pointCount(), 3);
    EXPECT_FALSE(sk.getPoint(c));
    EXPECT_TRUE(sk.getPoint(b));
    const SketchLine* l2 = findLine(sk, line2);
    ASSERT_NE(l2, nullptr);
    EXPECT_EQ(l2->startPointId, b);
    EXPECT_EQ(l2->endPointId, d);
}

// A line whose two endpoints weld into one has no span left - it is removed.
TEST(SketchMerge, LineCollapsedToSinglePointIsRemoved) {
    Sketch sk;
    const int a = sk.addPoint(glm::vec2(0.0f, 0.0f));
    const int b = sk.addPoint(glm::vec2(10.0f, 0.0f));
    const int lineId = sk.addLine(a, b);

    EXPECT_TRUE(sk.mergePoints(b, a));

    EXPECT_EQ(findLine(sk, lineId), nullptr);
    EXPECT_TRUE(sk.getLines().empty());
    EXPECT_EQ(sk.pointCount(), 1);
    EXPECT_TRUE(sk.getPoint(a));
    EXPECT_FALSE(sk.getPoint(b));
}

// A two-point spline whose endpoints weld into one is left with a single
// distinct control point - nothing drawable remains, so the spline is removed.
TEST(SketchMerge, TwoPointSplineWeldedAwayIsRemoved) {
    Sketch sk;
    const int a = sk.addPoint(glm::vec2(0.0f, 0.0f));
    const int b = sk.addPoint(glm::vec2(10.0f, 0.0f));
    sk.addSpline({a, b});

    EXPECT_TRUE(sk.mergePoints(b, a));

    EXPECT_TRUE(sk.getSplines().empty());
    EXPECT_EQ(sk.pointCount(), 1);
    EXPECT_TRUE(sk.getPoint(a));
}

// Constraints reference point ids too (entityA / entityB) - those rewire
// alongside the geometry instead of being left pointing at a deleted point.
TEST(SketchMerge, ConstraintPointEntitiesRewire) {
    Sketch sk;
    const int a = sk.addPoint(glm::vec2(0.0f, 0.0f));
    const int b = sk.addPoint(glm::vec2(10.0f, 0.0f));
    Constraint c;
    c.type = ConstraintType::Distance;
    c.entityA = a;
    c.entityB = b;
    sk.addConstraint(c);

    EXPECT_TRUE(sk.mergePoints(b, a));

    ASSERT_EQ(sk.getConstraints().size(), 1);
    EXPECT_EQ(sk.getConstraints()[0].entityA, a);
    EXPECT_EQ(sk.getConstraints()[0].entityB, a);
}
